 if not st.session_state.get('started'):
  st.write('🧺 상품 등록　🍊 제철 추천　🍳 요리 안내')
  if st.button('시작하기 →',type='primary',use_container_width=True):st.session_state.started=True;st.rerun()
  st.stop()
 music()
 ad=st.selectbox('✨ 농장 매거진',[ '오늘의 한입','상큼한 하루','제철 탐험'],label_visibility='collapsed')
 ads={'오늘의 한입':'🎤 가상 진행자 한입이: 오늘은 제철 과일 한 접시 어때요?','상큼한 하루':'🌟 가상 캐릭터 새봄: 요구르트에 과일을 톡! 오늘 간식 완성.','제철 탐험':'🍊 가상 캐릭터 귤대장: 이번 달 과일, 사진으로 골라봐요!'}
 st.info(ads[ad]);st.caption('앱 자체 홍보 · 가상 캐릭터 · 실제 연예인의 추천이 아닙니다.')
 a,b=st.columns(2)
 with a:st.link_button('🧺 판매 준비','?view=manage',use_container_width=True)
 with b:st.link_button('🍊 제철 구경','?view=season',use_container_width=True)
 month=datetime.now(timezone(timedelta(hours=9))).month
 names=MONTH_PICKS.get(month,[])
 if names:
  f=names[0];st.subheader(f'{month}월의 한입 · {f}');image(f)
