if view=='season':
 st.title('🍊 이달의 과일')
 month=st.selectbox('📅 월',range(1,13),index=datetime.now(timezone(timedelta(hours=9))).month-1,format_func=lambda m:f'{m}월')
 names=MONTH_PICKS.get(month,[])
 st.caption('제공된 월별 자료 참고 · 산지·재배 방식에 따라 달라요. 4월 키위는 추가 유통 추천이며 자료의 제철 항목은 아닙니다.')
 if not names:st.info('추천 과일을 준비 중이에요.');st.stop()
 cols=st.columns(2)
 for i,fruit in enumerate(names[:4]):
  with cols[i%2]:
   image(fruit)
   st.caption(fruit)
 f=st.selectbox('🍎 자세히 보기',names,key=f'season_fruit_{month}')
 g=FRUIT_GUIDE[f]
 tab=st.segmented_control('더 보기',['🍳 요리','💚 좋은 점','⚠ 주의'],default='🍳 요리')
 if tab=='🍳 요리':
  st.write(g.get('recipe',''))
  st.caption('🥣 응용: 샐러드 · 오트밀 · 요구르트는 생식 가능한 과일만! 매실은 반드시 안전하게 가공하세요.')
 elif tab=='💚 좋은 점':st.write(g.get('good',''))
 else:st.warning(g.get('caution',''))
 st.stop()
# Private screens: credentials never travel in the URL.
password=secret('ADMIN_PASSWORD')
if not password:st.warning('🔒 Streamlit Secrets에 ADMIN_PASSWORD를 설정해 주세요.');st.stop()
if not st.session_state.get('authenticated'):
 st.title('🔒 농장 관리')
 with st.form('login'):
  entered=st.text_input('관리 비밀번호',type='password');ok=st.form_submit_button('들어가기',use_container_width=True)
 if ok:
  if time.time()<st.session_state.get('retry_at',0):st.error('잠시 후 다시 시도해 주세요.')
  elif hmac.compare_digest(entered.encode(),password.encode()):st.session_state.authenticated=True;st.rerun()
  else:st.session_state.retry_at=time.time()+3;st.error('비밀번호를 확인해 주세요.')
 st.stop()
if not PERSISTENT:st.caption('🧪 체험 모드 · 재시작하면 저장 내용이 사라질 수 있어요.')
try:rows=read_products()
except RuntimeError as e:st.error(str(e));st.stop()
if view=='qr':
 st.title('📱 QR 만들기')
 if not PERSISTENT or not valid_url(APP_URL):st.info('영구 저장소와 APP_URL 설정 후 공유할 수 있어요.');st.stop()
 kind=st.segmented_control('종류',['🍊 제철 홍보','📦 상품 안내'],default='🍊 제철 홍보')
 if kind=='🍊 제철 홍보':qr(APP_URL+'?view=season')
 elif rows:
  r=st.selectbox('상품',rows,format_func=lambda r:r['public_data'].get('name','상품'));qr(APP_URL+'?'+urlencode({'product':r['id']}))
 else:st.info('먼저 상품을 저장해 주세요.')
 st.stop()
st.title('🧺 상품 관리')
ids=['new']+[r['id'] for r in rows];lookup={r['id']:r for r in rows}
pick=st.selectbox('상품',ids,format_func=lambda x:'➕ 새 상품' if x=='new' else lookup[x]['public_data'].get('name','상품'))
r=lookup.get(pick,{});pub=r.get('public_data',{});priv=r.get('private_data',{});key=pick
stage=st.segmented_control('작업',['① 상품','② 가격','③ 소개글'],default='① 상품',key='stage_'+key)
# Keep draft across stage changes without overwriting existing public/private fields.
if 'draft_'+key not in st.session_state:st.session_state['draft_'+key]={'public':dict(pub),'private':dict(priv)}
draft=st.session_state['draft_'+key];d=draft['public'];v=draft['private']
if stage=='① 상품':
 fruits=list(FRUIT_GUIDE);f=st.selectbox('🍎 과일',fruits,index=fruits.index(d.get('fruit')) if d.get('fruit') in fruits else 0,key='fruit_'+key)
 image(f,d.get('photo',''))
 with st.form('product_'+key):
  name=st.text_input('상품명',d.get('name',f))
  weight=st.text_input('포장 중량',d.get('weight',''),placeholder='예: 3kg 한 상자')
  features=st.text_input('한 줄 특징',d.get('features',''),placeholder='예: 모양이 고르지 않은 가정용')
  shop=st.text_input('판매 링크',d.get('shop',''),placeholder='https://…')
  up=st.file_uploader('📷 실제 상품 사진',type=['jpg','jpeg','png'])
  if st.form_submit_button('💾 상품 저장',use_container_width=True):
   if not name.strip():st.error('상품명을 적어 주세요.')
   elif shop and not valid_url(shop):st.error('판매 링크를 확인해 주세요.')
   else:
    try:
     d.update(fruit=f,name=name.strip(),weight=weight,features=features,shop=shop,unit=d.get('unit','상자'))
     if up:d['photo']=photo_data(up)
     rid=str(uuid.uuid4()) if pick=='new' else pick
     save_product({'id':rid,'public_data':d,'private_data':v});st.success('저장했어요! 위 상품 목록에서 선택하세요.')
    except (RuntimeError,ValueError,OSError) as e:st.error(str(e))
elif stage=='② 가격':
 with st.form('price_'+key):
  price=st.number_input('판매가 (원)',min_value=0,value=int(v.get('price',0)),step=100)
  cost=st.number_input('원가 + 포장비 + 배송비 (원)',min_value=0,value=int(v.get('total_cost',0)),step=100)
  rate=st.number_input('수수료 (%)',min_value=0.0,max_value=99.0,value=float(v.get('rate',0)))
  if st.form_submit_button('계산 · 저장',use_container_width=True):
   if pick=='new':st.warning('먼저 상품을 저장하고 목록에서 선택하세요.')
   else:
    v.update(price=price,total_cost=cost,rate=rate)
    try:save_product({'id':pick,'public_data':d,'private_data':v});st.metric('상자당 예상 이익',f'{money(price*(1-rate/100)-cost):,}원')
    except RuntimeError as e:st.error(str(e))
 st.caption('입력 비용 기준 추정치 · 고객 배송비 수입·할인·세금은 별도로 고려하세요.')
else:
 f=d.get('fruit','사과');g=FRUIT_GUIDE.get(f,{})
 st.code(d.get('name',f)+' '+d.get('weight','')+'\n'+d.get('features',''),language=None)
 st.write('🍳 고객용 먹는 방법');st.write(d.get('recipe') or g.get('recipe',''))
 st.write('❄ 보관');st.write(d.get('storage') or g.get('storage',''))
